import express, { Express } from "express";
import { randomUUID } from "node:crypto";
import { TaskService } from "../application/task-service";
import { InMemoryProjectRepository, InMemoryTaskRepository, InMemoryUserRepository } from "./in-memory-repositories";
import { errorHandler, TaskController } from "./task-controller";

export function createApp(): Express {
  const app = express();
  const taskService = new TaskService(
    new InMemoryProjectRepository(),
    new InMemoryTaskRepository(),
    new InMemoryUserRepository(),
    randomUUID,
  );
  app.use(express.json());
  new TaskController(taskService).register(app);
  app.use(errorHandler);
  return app;
}

export function startServer(port = Number(process.env.PORT ?? 3000)): void {
  createApp().listen(port, () => {
    console.log(`Task API listening on port ${port}`);
  });
}

if (require.main === module) startServer();

